import { createAdabiLesson } from "../shared.js";

export const source = ":::exam-question\nid: it-t-p012-q01\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 1\nquestion: كم عدد الخانات الثنائية التي يتكون منها عنوان الـ MAC؟ وكيف يتم تمثيله بأنظمة التشغيل؟ ادعم إجابتك بمثال.\nreference: الكتاب · ص 10 · PDF 12 · السؤال 1\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nكم عدد الخانات الثنائية التي يتكون منها عنوان الـ MAC؟ وكيف يتم تمثيله بأنظمة التشغيل؟ ادعم إجابتك بمثال.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nيتكوّن عنوان MAC من 48 بت،\n\nويظهر عادةً في 12 خانة سداسية عشرية، مقسمة إلى ست مجموعات مثل `00:1A:2B:3C:4D:5E`.\nsolution:\nيقول الكتاب:\n\n> يتكون عنوان MAC من **48 بت**، و يتم تمثيله في أنظمة التشغيل على هيئة نظام العد السادس عشر Hexadecimal،\n\nالكتاب، ص 4 (صفحة PDF 6).\n\nلتمييز طول العنوان عن طريقة كتابته:\n\n- **الطول الثنائي:** 48 بت.\n- **التمثيل الظاهر:** كل أربع بتات تقابل خانة سداسية عشرية واحدة.\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>48</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>12</mn></mrow></math>\n```\n\nإذن نكتب العنوان في **12 خانة سداسية عشرية**، تجمع عادةً في ست مجموعات من خانتين، مثل `00:1A:2B:3C:4D:5E`. المثال يوضح الصيغة، ولا يدل على جهاز بعينه.\n:::\n\n:::exam-question\nid: it-t-p012-q02\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 2\nquestion: لماذا يتم تصنيف عنوان MAC كعنوان فيزيائي؟\nreference: الكتاب · ص 10 · PDF 12 · السؤال 2\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nلماذا يتم تصنيف عنوان MAC كعنوان فيزيائي؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nلأنه يرتبط بواجهة الشبكة نفسها، ويُعيَّن لها من المصنّع في النموذج الوارد في الكتاب، ويبقى مع الواجهة عند نقلها إلى شبكة أخرى.\nsolution:\nالعنوان الفيزيائي مرتبط ببطاقة الشبكة نفسها، لا باسم الشبكة المتصل بها الجهاز. يوضح الكتاب أن المصنّع ينشئ MAC على البطاقة، وأن الجهاز يحتفظ به ما دام يستخدم البطاقة نفسها. لذلك نقل الجهاز إلى شبكة أخرى لا يغيّر عنوان بطاقته الأصلي.\n\nالكتاب، ص 4 (صفحة PDF 6).\n:::\n\n:::exam-question\nid: it-t-p012-q03\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 3\nquestion: ما وظيفة بطاقة واجهة الشبكة الموجودة في جهاز الحاسوب؟\nreference: الكتاب · ص 10 · PDF 12 · السؤال 3\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما وظيفة بطاقة واجهة الشبكة الموجودة في جهاز الحاسوب؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nتصل بطاقة واجهة الشبكة الحاسوب بوسيط الاتصال السلكي أو اللاسلكي، وتمكّنه من إرسال إطارات البيانات واستقبالها.\nsolution:\nيقول الكتاب:\n\n> وهي الأداة التي **تربط جهاز الحاسوب بالوسيط**\n\nالكتاب، ص 3 (صفحة PDF 5).\n\nتؤدي البطاقة دور الواجهة بين الجهاز ووسيط الاتصال، ويذكر الكتاب أنها تتحقق من خلو الوسيط من الإشارات قبل الإرسال في النموذج الذي يشرحه.\n:::\n\n:::exam-question\nid: it-t-p012-q04\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 4\nquestion: ماذا يستفيد المحول Switch من حقل FCS الموجود في ذيل الإطار؟\nreference: الكتاب · ص 10 · PDF 12 · السؤال 4\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nماذا يستفيد المحول Switch من حقل FCS الموجود في ذيل الإطار؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nيعيد المحوّل حساب قيمة فحص الإطار ويقارنها بقيمة FCS المرفقة.\n\nإذا اختلفتا يرفض الإطار لأن بياناته قد تغيرت أثناء النقل.\nsolution:\nيستخدم المحوّل حقل **FCS لفحص سلامة الإطار**، وفق الخطوات الآتية:\n\n1. يعيد حساب قيمة الفحص للإطار المستلَم.\n2. يقارن القيمة المحسوبة بقيمة FCS المرسَلة مع الإطار.\n3. إذا تطابقت القيمتان، يتابع معالجة الإطار؛ وإذا اختلفتا، يهمل الإطار لأنه تعرض لخطأ أثناء النقل.\n\nإذن FCS يفحص سلامة البيانات، أما اختيار منفذ الإرسال فيعتمد عنوان MAC الهدف.\n\nالكتاب، ص 10 (صفحة PDF 12).\n:::\n\n:::exam-question\nid: it-t-p012-q05\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 5\nquestion: كيف يتخذ المحول Switch القرار المناسب لتحويل الرسالة للمنفذ الصحيح؟\nreference: الكتاب · ص 10 · PDF 12 · السؤال 5\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nكيف يتخذ المحول Switch القرار المناسب لتحويل الرسالة للمنفذ الصحيح؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nيقرأ عنوان MAC للهدف ويبحث عنه في جدول عناوينه، فيرسل الإطار إلى المنفذ المقابل إن كان معروفًا.\n\nوإذا لم يكن معروفًا يرسله عبر المنافذ الأخرى ضمن الشبكة المحلية، باستثناء منفذ الاستقبال.\nsolution:\n1. يقرأ المحوّل عنوان MAC **للهدف** من رأس الإطار.\n2. يبحث عن هذا العنوان في جدول عناوين MAC.\n3. إذا وجد العنوان، يرسل الإطار عبر المنفذ المسجَّل له.\n4. إذا لم يجده، ينشر الإطار عبر المنافذ الأخرى في الشبكة المحلية، باستثناء المنفذ الذي دخل منه.\n\nبهذا لا يخلط بين تعلّم عنوان المصدر واختيار منفذ الهدف. الكتاب، ص 8–10 (صفحات PDF 10–12).\n:::\n\n:::exam-question\nid: it-t-p012-q06\ntitle: الكتاب · ص 10 · PDF 12 · السؤال 6\nquestion: كيف يقوم المحول Switch بتعبئة جدول عناوين MAC؟\nreference: الكتاب · ص 10 · PDF 12 · السؤال 6\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nكيف يقوم المحول Switch بتعبئة جدول عناوين MAC؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nيقرأ المحوّل عنوان MAC المصدر من كل إطار وارد، ويربطه بالمنفذ الذي استقبل الإطار في جدول عناوين MAC.\nsolution:\nيتعلّم المحوّل موقع الجهاز من **الإطارات الواردة**:\n\n1. يقرأ عنوان MAC **المصدر**.\n2. يربط هذا العنوان بالمنفذ الذي استقبل الإطار، ثم يسجل الربط في جدول العناوين أو يحدّثه.\n\nعندما يصبح هذا الجهاز هدفًا لإطار لاحق، يجد المحوّل منفذه في الجدول، فلا يحتاج إلى إرسال الإطار إلى الجميع.\n\nالكتاب، ص 9–10 (صفحات PDF 11–12).\n:::\n\n:::mcq\nid: it-t-p028-q01\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 1-1\nkicker: الكتاب · ص 26 · PDF 28 · السؤال 1-1\nreference: الكتاب · ص 26 · PDF 28 · السؤال 1-1\nquestion: أي العناوين الآتية يستخدمه المحول Switch لتحويل الإطار بين أجهزة الشبكة المحلية؟\n- [ ] option-1 | Email address.\n- [ ] option-2 | IP address.\n- [ ] option-3 | Port address.\n- [x] option-4 | Mac address.\nexplanation:\nالمطلوب تحويل **إطار داخل الشبكة المحلية**، وهي وظيفة طبقة ربط البيانات؛ لذلك العنوان المستخدم هو **MAC**. عنوان IP يستخدمه الموجه لتوجيه الحزم بين الشبكات، والبريد الإلكتروني ليس عنوان تحويل إطار.\n\nالكتاب، ص 4، 8–9 (صفحات PDF 6، 10–11).\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### أسئلة الوحدة\n:::\n\n:::exam-question\nid: it-t-p028-q06\ntitle: الكتاب · ص 26 · PDF 28 · السؤال 3\nquestion: ما تأثير كل من عنوان MAC المصدر والهدف الموجودين في رأس الإطار على أداء المحول Switch؟\nreference: الكتاب · ص 26 · PDF 28 · السؤال 3\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما تأثير كل من عنوان MAC المصدر والهدف الموجودين في رأس الإطار على أداء المحول Switch؟\n\n### أسئلة الوحدة\nfinal-answer:\n- يستعمل المحوّل عنوان MAC المصدر لتعلّم المنفذ الذي وصل منه الإطار وتحديث الجدول.\n- ويبحث عن عنوان MAC الوجهة في الجدول ليختار منفذ إرسال الإطار.\nsolution:\nللعنوانين وظيفتان مختلفتان:\n\n- **المصدر للتعلّم:** يسجل المحوّل عنوان المصدر مع منفذ دخول الإطار.\n- **الهدف للتحويل:** يبحث عن عنوان الهدف في الجدول ليختار منفذ الإرسال.\n\nإذن يبني المحول معرفته من الإطارات الداخلة، ويستخدم هذه المعرفة لتوجيه الإطارات اللاحقة. الكتاب، ص 8–10 (صفحات PDF 10–12).\n:::\n\n:::exam-question\nid: it-t-p029-q01\ntitle: الكتاب · ص 27 · PDF 29 · السؤال 4\nquestion: ما المقصود بجدول عناوين الـ MAC داخل المحول Switch؟\nreference: الكتاب · ص 27 · PDF 29 · السؤال 4\nanswer-label: إجابة مستندة إلى الكتاب\nbody:\nما المقصود بجدول عناوين الـ MAC داخل المحول Switch؟\n\n### أسئلة الوحدة\nfinal-answer:\nجدول يحتفظ فيه المحوّل بربط كل عنوان MAC متعلَّم بالمنفذ الذي استقبل منه الإطارات، ليستخدمه في توجيه الإطارات اللاحقة.\nsolution:\nيقول الكتاب:\n\n> يوجد داخل كل محول جدول **يربط عناوين MAC بأرقام المنافذ المتصلة بها**.\n\nالكتاب، ص 9 (صفحة PDF 11).\n\nفكرة الجدول هي الربط بين **هوية الجهاز ومنفذه**؛ فعند وصول إطار إلى هذا الجهاز، يبحث المحوّل عن عنوانه ليعرف منفذ الإرسال.\n:::\n\n:::exam-question\nid: it-t-p029-q02\ntitle: الكتاب · ص 27 · PDF 29 · السؤال 5\nquestion: كم عنوان MAC مختلفًا يمكن إنشاؤه؟\nreference: الكتاب · ص 27 · PDF 29 · السؤال 5\nanswer-label: إجابة نموذجية للتدريب\nbody:\nكم عنوان MAC مختلفًا يمكن إنشاؤه؟\n\n### أسئلة الوحدة\nfinal-answer:\nتوجد 2⁴⁸ قيمة ثنائية ممكنة نظريًا، أي 281,474,976,710,656 قيمة.\nsolution:\nعنوان MAC طوله **48 بت**، ولكل بت احتمالان: 0 أو 1. عدد التركيبات إذن:\n\n$$2^{48}=281474976710656$$\n\nهذا هو عدد القيم الثنائية النظرية؛ لا نضرب 48 في 2 لأننا نعد جميع التركيبات، لا عدد الرموز. الكتاب، ص 4 (صفحة PDF 6).\n:::\n\n:::mcq\nid: it-e-p042-q01\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-1 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-1 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-1 · 2019 — الدورة الأولى\nquestion: ماذا يسمى تنسيق الرسالة في طبقة ربط البيانات؟\n- [x] option-1 | إطار Frame\n- [ ] option-2 | بيانات Data\n- [ ] option-3 | قطعة Segment\n- [ ] option-4 | حزمة Packet\nexplanation:\nيقول الكتاب:\n\n> يسمى تنسيق الرسالة في هذه الطبقة ب**إطار (Frame)**.\n\nالكتاب، ص 3\n\nالسؤال يحدد **طبقة ربط البيانات**؛ وفي هذه الطبقة تكون وحدة البيانات إطارًا، لذلك نختار **Frame**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q02\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-2 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-2 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-2 · 2019 — الدورة الأولى\nquestion: كم عدد الخانات الثنائية التي يتكون منها العنوان الفيزيائي؟\n- [ ] option-1 | 16 بت\n- [ ] option-2 | 32 بت\n- [x] option-3 | 48 بت\n- [ ] option-4 | 64 بت\nexplanation:\nيقول الكتاب:\n\n> يتكون عنوان MAC من **48 بت**، و يتم تمثيله في أنظمة التشغيل على هيئة نظام العد السادس عشر Hexadecimal،\n\nالكتاب، ص 4\n\nالمطلوب عدد **البتات** في العنوان، لا عدد الخانات المكتوبة؛ طول MAC هو **48 بت**، بينما تمثيله السادس عشري يتكون من 12 خانة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q03\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-3 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-3 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-3 · 2019 — الدورة الأولى\nquestion: ماذا يسمى نظام العنونة الفيزيائية والذي يكون فريدًا على مستوى بطاقات الشبكة في العالم؟\n- [ ] option-1 | Port Address\n- [x] option-2 | Mac Address\n- [ ] option-3 | IP Address\n- [ ] option-4 | Email Address\nexplanation:\nيقول الكتاب:\n\n> عنوان الـ **MAC** هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nعبارة **العنونة الفيزيائية لبطاقة الشبكة** تدل على MAC؛ أما IP فهو العنوان المنطقي.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q04\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-4 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-4 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-4 · 2019 — الدورة الأولى\nquestion: أي من الطبقات تستخدم لتنظيم عملية الإرسال على الوسائط المشتركة بين عدة أجهزة لضمان عدم تداخل الإشارات؟\n- [ ] option-1 | الأولى\n- [x] option-2 | الثانية\n- [ ] option-3 | الثالثة\n- [ ] option-4 | الرابعة\nexplanation:\nيقول الكتاب:\n\n> تأتي **الطبقة الثانية** لتنظم عملية الإرسال على الوسائط المشتركة بين عدة أجهزة لضمان عدم تداخل الإشارات، وبالتالي تداخل البيانات وضياعها.\n\nالكتاب، ص 3\n\nالمطلوب تنظيم مشاركة وسيط الإرسال، وهي وظيفة **الطبقة الثانية: ربط البيانات**. أما نقل الإشارات عبر الوسيط فيخص الطبقة الفيزيائية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q05\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-5 · 2019 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-5 · 2019 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-5 · 2019 — الدورة الأولى\nquestion: ما العدد الثنائي المكافئ للعدد العشري (31)₁₀؟\n- [x] option-1 | (11111)₂\n- [ ] option-2 | (11110)₂\n- [ ] option-3 | (10111)₂\n- [ ] option-4 | (10000)₂\nexplanation:\nنحوّل العدد العشري إلى مجموع أوزان الخانات الثنائية:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>31</mn><mo>=</mo><mn>16</mn><mo>+</mo><mn>8</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>1</mn></mrow></math>\n```\n\nالأوزان 16، 8، 4، 2، 1 موجودة كلها في المجموع؛ لذلك نضع **1 في الخانات الخمس**:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>31</mn><mn>10</mn></msub><mo>=</mo><msub><mn>11111</mn><mn>2</mn></msub></mrow></math>\n```\n\nأما `11110` فيساوي 30؛ لذا فالإجابة الصحيحة **11111**، وفق التصحيح الموثق للمفتاح.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q06\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-6 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-6 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-6 · 2019 — الدورة الثانية\nquestion: ما الجهاز الذي يقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية؟\n- [x] option-1 | محول الشبكة Switch\n- [ ] option-2 | كرت الشبكة NIC\n- [ ] option-3 | الإطار Frame\n- [ ] option-4 | الموجه Router\nexplanation:\nيقول الكتاب:\n\n> **محول الشبكة Switch**: جهاز يقوم بربط مجموعة أجهزة في شبكة محلية على شكل مخطط نجمي Star عبر نقطة مركزية ترتبط بها جميع أجهزة الحاسوب، حيث يقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية.\n\nالكتاب، ص 7\n\nالوصف يجمع بين **ربط عدة أجهزة** و**تنظيم مرور البيانات بينها** داخل الشبكة المحلية؛ لذلك يطابق المحوّل Switch.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q07\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-7 · 2019 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-7 · 2019 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-7 · 2019 — الدورة الثانية\nquestion: ما العدد الثنائي المكافئ للعدد (A)₁₆؟\n- [ ] option-1 | (0111)₂\n- [ ] option-2 | (1110)₂\n- [x] option-3 | (1010)₂\n- [ ] option-4 | (1000)₂\nexplanation:\nيمثل الرمز **A العدد 10** في النظام السادس عشر. نكتب 10 باستعمال الأوزان الثنائية:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>10</mn><mo>=</mo><mn>8</mn><mo>+</mo><mn>2</mn></mrow></math>\n```\n\nعند الأوزان 8، 4، 2، 1 تكون الخانات بالترتيب **1، 0، 1، 0**:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">A</mi><mn>16</mn></msub><mo>=</mo><msub><mn>1010</mn><mn>2</mn></msub></mrow></math>\n```\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q08\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-8 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-8 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-8 · 2019 — الدورة الثالثة\nquestion: نظام العنونة الفيزيائية يتم إنشاؤه من قبل:\n- [ ] option-1 | مصمم الشبكة\n- [ ] option-2 | المبرمج\n- [ ] option-3 | المستخدم\n- [x] option-4 | المصنع\nexplanation:\nيقول الكتاب:\n\n> عنوان الـ MAC هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل **المصنع** بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nيسأل السؤال عن الجهة التي تنشئ عنوان البطاقة في نموذج الكتاب؛ وهي **المصنّع**، وليس مستخدم الشبكة أو مصممها.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q09\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-9 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-9 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-9 · 2019 — الدورة الثالثة\nquestion: إذا كانت نتيجة فحص الإطار باستخدام FCS أنه غير صالح، فإن محول الشبكة يقوم بـ:\n- [ ] option-1 | إعادة إرساله للمصدر\n- [x] option-2 | التخلص منه\n- [ ] option-3 | متابعة الإرسال\n- [ ] option-4 | تخزينه داخل الجدول\nexplanation:\nيقول الكتاب:\n\n> فإذا كانت النتيجة الإطار غير صالح يقوم محول الشبكة **بالتخلص منه**.\n\nالكتاب، ص 10\n\nفشل فحص FCS يعني أن الإطار غير صالح؛ لذلك **يتخلص المحوّل منه** بدل متابعة إرساله.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q10\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-10 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-10 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-10 · 2019 — الدورة الثالثة\nquestion: الجهاز الذي يقوم بربط مجموعة من الأجهزة في الشبكة المحلية على شكل مخطط نجمي Star:\n- [x] option-1 | Switch\n- [ ] option-2 | Repeater\n- [ ] option-3 | Router\n- [ ] option-4 | Server\nexplanation:\nيقول الكتاب:\n\n> **محول الشبكة Switch**: جهاز يقوم بربط مجموعة أجهزة في شبكة محلية على شكل مخطط نجمي Star عبر نقطة مركزية ترتبط بها جميع أجهزة الحاسوب، حيث يقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية.\n\nالكتاب، ص 7\n\nكل جهاز يرتبط بنقطة مركزية هي **المحوّل Switch**؛ وهذا هو المخطط النجمي المذكور في السؤال.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q11\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-11 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-11 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-11 · 2019 — الدورة الثالثة\nquestion: ما العدد الثنائي المكافئ للعدد (36)₁₆؟\n- [x] option-1 | (00110110)₂\n- [ ] option-2 | (11000011)₂\n- [ ] option-3 | (00001111)₂\n- [ ] option-4 | (11110000)₂\nexplanation:\nنحوّل كل رقم سادس عشري إلى **أربع خانات ثنائية**، مع الحفاظ على ترتيب الرقمين:\n\n- `3` يقابله `0011`.\n- `6` يقابله `0110`.\n\nنصل المجموعتين من دون تبديلهما:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>36</mn><mn>16</mn></msub><mo>=</mo><msub><mn>00110110</mn><mn>2</mn></msub></mrow></math>\n```\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q12\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-12 · 2019 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-12 · 2019 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-12 · 2019 — الدورة الثالثة\nquestion: ماذا يسمى نظام العنونة الفيزيائية والذي يكون فريدًا على مستوى بطاقات الشبكة في العالم\n- [ ] option-1 | Port Address\n- [x] option-2 | Mac Address\n- [ ] option-3 | IP Address\n- [ ] option-4 | Email Address\nexplanation:\nيقول الكتاب:\n\n> عنوان الـ **MAC** هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nالمفتاح في السؤال هو ارتباط العنوان **ببطاقة الشبكة**؛ وهذا وصف عنوان **MAC**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q13\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-13 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-13 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-13 · 2020 — الدورة الأولى\nquestion: ما قيمة العدد (A7)₁₆ في النظام الثنائي؟\n- [ ] option-1 | 01111010\n- [x] option-2 | 10100111\n- [ ] option-3 | 11100101\n- [ ] option-4 | 01011110\nexplanation:\nكل خانة سادسة عشرية تقابل **أربع خانات ثنائية**:\n\n- `A` تقابل `1010`.\n- `7` تقابل `0111`.\n\nنصل المجموعتين بترتيب الرقمين:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">A7</mi><mn>16</mn></msub><mo>=</mo><msub><mn>10100111</mn><mn>2</mn></msub></mrow></math>\n```\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q14\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-14 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-14 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-14 · 2020 — الدورة الأولى\nquestion: كم عنوان MAC مختلفًا يمكن إنشاؤه؟\n- [ ] option-1 | 2⁵⁶\n- [x] option-2 | 2⁴⁸\n- [ ] option-3 | 2³²\n- [ ] option-4 | 2¹⁶\nexplanation:\nطول العنوان الفيزيائي في الكتاب **48 بت**، ولكل بت احتمالان: 0 أو 1. للحصول على عدد العناوين نضرب احتمالَي كل خانة في احتمالات الخانات الأخرى:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>2</mn><mo>×</mo><mn>2</mn><mo>×</mo><mo>⋯</mo><mo>×</mo><mn>2</mn><mo>=</mo><msup><mn>2</mn><mn>48</mn></msup></mrow></math>\n```\n\nإذن العدد **2⁴⁸ عنوانًا مختلفًا**؛ فالأس يساوي عدد البتات، وليس حاصل ضرب 48 في 2.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p042-q15\ntitle: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-15 · 2020 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-15 · 2020 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 42 · PDF 42 · السؤال 1-15 · 2020 — الدورة الأولى\nquestion: ما الجهاز الذي يتخذ القرار المناسب لتحويل الرسالة للمنفذ الصحيح في طبقة ربط البيانات\n- [x] option-1 | محول الشبكة\n- [ ] option-2 | بطاقة واجهة الشبكة\n- [ ] option-3 | الموجه\n- [ ] option-4 | المعيد\nexplanation:\nيقول الكتاب:\n\n> تقوم محولات الشبكة بتحويل الرسالة للجهاز الهدف عبر المنفذ المناسب بناءً على الحقل الذي يحتوي على **عنوان الـ MAC الهدف** الموجود في بداية الرسالة (الإطار) كما في الشكل أدناه.\n\nالكتاب، ص 8\n\nالمحوّل هو من يقرأ **MAC الهدف** ويبحث عن منفذه في الجدول؛ لذلك هو الجهاز الذي يتخذ قرار التحويل.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q01\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-16 · 2020 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-16 · 2020 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-16 · 2020 — الدورة الثانية\nquestion: ما الحقل الذي يستخدمه المحول للتأكد من صلاحية الإطار في طبقة ربط البيانات\n- [ ] option-1 | عنوان الهدف\n- [ ] option-2 | عنوان المصدر\n- [ ] option-3 | جسم الرسالة\n- [x] option-4 | تفحص الأخطاء\nexplanation:\nيقول الكتاب:\n\n> يستخدم المحول قيمة FCS (Frame Check Sequence) الموجودة في **حقل تفحص الأخطاء** الموجودة في نهاية الرسالة (الإطار).\n\nالكتاب، ص 10\n\nيسأل السؤال عن **صلاحية الإطار**، لذلك نختار حقل تفحص الأخطاء FCS؛ أما عنوان الهدف فيستخدم لاختيار منفذ الإرسال.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q02\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-17 · 2020 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-17 · 2020 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-17 · 2020 — الدورة الثانية\nquestion: كم خانة تخصص لكل عنصر من عناصر النظام السادس عشر لتمثيله بالنظام الثنائي\n- [x] option-1 | 4\n- [ ] option-2 | 8\n- [ ] option-3 | 12\n- [ ] option-4 | 16\nexplanation:\nالخانة السادسة عشرية لها **16 احتمالًا**، من 0 إلى F. نحتاج إلى عدد من البتات يتيح العدد نفسه من الاحتمالات:\n\n```mathml\n<math dir=\"ltr\"><mrow><msup><mn>2</mn><mn>4</mn></msup><mo>=</mo><mn>16</mn></mrow></math>\n```\n\nإذن تمثل الخانة السادسة عشرية الواحدة **أربع بتات**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q03\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-18 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-18 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-18 · 2020 — الدورة الثالثة\nquestion: ما العدد السادس عشر الذي يقابل العدد (11101)₂؟\n- [ ] option-1 | 13\n- [ ] option-2 | 31\n- [x] option-3 | 1D\n- [ ] option-4 | D1\nexplanation:\nنجمع البتات **من اليمين** في مجموعات من أربع، ونكمل المجموعة اليسرى بأصفار:\n\n`11101 → 0001 | 1101`\n\n- `0001` تمثل `1`.\n- `1101` تمثل `13`، أي الرمز `D`.\n\nنكتب الرمزين بترتيب المجموعتين:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>11101</mn><mn>2</mn></msub><mo>=</mo><msub><mi mathvariant=\"normal\">1D</mi><mn>16</mn></msub></mrow></math>\n```\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q04\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-19 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-19 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-19 · 2020 — الدورة الثالثة\nquestion: ما الحقل الذي يستخدمه المحول للتأكد من صلاحية الإطار في طبقة ربط البيانات؟\n- [ ] option-1 | عنوان الهدف\n- [ ] option-2 | عنوان المصدر\n- [ ] option-3 | جسم الرسالة\n- [x] option-4 | تفحص الأخطاء\nexplanation:\nيقول الكتاب:\n\n> يستخدم المحول قيمة FCS (Frame Check Sequence) الموجودة في **حقل تفحص الأخطاء** الموجودة في نهاية الرسالة (الإطار).\n\nالكتاب، ص 10\n\nعند التحقق من سلامة الإطار نرجع إلى **FCS في نهايته**، وليس إلى حقلي عنوان المصدر أو الهدف.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q05\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-20 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-20 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-20 · 2020 — الدورة الثالثة\nquestion: ما العدد الثنائي المكافئ للعدد العشري (31)₁₀؟\n- [x] option-1 | (11111)₂\n- [ ] option-2 | (11110)₂\n- [ ] option-3 | (10111)₂\n- [ ] option-4 | (10000)₂\nexplanation:\nنحوّل العدد العشري إلى مجموع أوزان الخانات الثنائية:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>31</mn><mo>=</mo><mn>16</mn><mo>+</mo><mn>8</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>1</mn></mrow></math>\n```\n\nالأوزان 16، 8، 4، 2، 1 موجودة كلها في المجموع؛ لذلك نضع **1 في الخانات الخمس**:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>31</mn><mn>10</mn></msub><mo>=</mo><msub><mn>11111</mn><mn>2</mn></msub></mrow></math>\n```\n\nأما `11110` فيساوي 30؛ لذا فالإجابة الصحيحة **11111**، وفق التصحيح الموثق للمفتاح.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q06\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-21 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-21 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-21 · 2020 — الدورة الثالثة\nquestion: ما الطبقة التي تنقل فيها البيانات على شكل إشارات عبر الوسائط المختلفة (سلكية ولا سلكية) في نظام OSI؟\n- [ ] option-1 | طبقة النقل\n- [ ] option-2 | طبقة الشبكة\n- [ ] option-3 | طبقة ربط البيانات\n- [x] option-4 | الطبقة الفيزيائية\nexplanation:\nيقول الكتاب:\n\n> **الطبقة الفيزيائية** التي تشكل البنية التحتية التي تنقل عليها البيانات على شكل إشارات عبر الوسائط المختلفة (سلكية ولاسلكية)،\n\nالكتاب، ص 3\n\nعبارة **إشارات عبر الوسائط** تشير إلى الطبقة الفيزيائية. أما طبقة ربط البيانات فتنظم الإرسال وتتعامل مع الإطارات.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q07\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-22 · 2020 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-22 · 2020 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-22 · 2020 — الدورة الثالثة\nquestion: أي من الطبقات تستخدم لتنظيم عملية الإرسال على الوسائط المشتركة بين عدة أجهزة لضمان عدم تداخل الإشارات؟\n- [ ] option-1 | الأولى\n- [x] option-2 | الثانية\n- [ ] option-3 | الثالثة\n- [ ] option-4 | الرابعة\nexplanation:\nيقول الكتاب:\n\n> تأتي **الطبقة الثانية** لتنظم عملية الإرسال على الوسائط المشتركة بين عدة أجهزة لضمان عدم تداخل الإشارات، وبالتالي تداخل البيانات وضياعها.\n\nالكتاب، ص 3\n\nتنظيم الإرسال لمنع تداخل الإشارات هو سبب اختيار **الطبقة الثانية**؛ نميّز ذلك عن مجرد نقل الإشارة في الطبقة الأولى.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q08\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-23 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-23 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-23 · 2021 — الدورة الأولى\nquestion: كم عدد الخانات الثنائية التي يتكون منها العنوان الفيزيائي؟\n- [ ] option-1 | 8 بت\n- [ ] option-2 | 32 بت\n- [x] option-3 | 48 بت\n- [ ] option-4 | 64 بت\nexplanation:\nيقول الكتاب:\n\n> يتكون عنوان MAC من **48 بت**، و يتم تمثيله في أنظمة التشغيل على هيئة نظام العد السادس عشر Hexadecimal،\n\nالكتاب، ص 4\n\nالبت هو خانة ثنائية واحدة. لذلك يكون جواب عدد الخانات الثنائية في MAC هو **48**، لا عدد مجموعاته الظاهرة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q09\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-24 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-24 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-24 · 2021 — الدورة الأولى\nquestion: ما النظام الذي يستخدم لتمثيل عنوان الـ MAC في أنظمة التشغيل؟\n- [ ] option-1 | الثنائي\n- [ ] option-2 | الثماني\n- [ ] option-3 | العشري\n- [x] option-4 | السادس عشر\nexplanation:\nيقول الكتاب:\n\n> يتكون عنوان MAC من 48 بت، و يتم تمثيله في أنظمة التشغيل على هيئة **نظام العد السادس عشر Hexadecimal**،\n\nالكتاب، ص 4\n\nالسؤال عن **طريقة كتابة العنوان** في أنظمة التشغيل؛ لذلك الجواب النظام السادس عشر. أما 48 بت فهي طوله في الصورة الثنائية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q10\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-25 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-25 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-25 · 2021 — الدورة الأولى\nquestion: ما نظام العنونة الذي توفره الطبقة الثانية؟\n- [ ] option-1 | الثنائي\n- [ ] option-2 | العشري\n- [x] option-3 | الفيزيائي\n- [ ] option-4 | المنطقي\nexplanation:\nيقول الكتاب:\n\n> تساعد طبقة ربط البيانات في إنشاء نظام عنونة محلي (**العنونة الفيزيائية**) حيث يستخدم هذا العنوان لتحويل الإطار Frame داخل حدود الشبكة.\n\nالكتاب، ص 4\n\nاستخدام العنوان لتحويل **الإطار داخل الشبكة** يربطه بالعنونة الفيزيائية التي توفرها الطبقة الثانية.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q11\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-26 · 2021 — الدورة الأولى\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-26 · 2021 — الدورة الأولى\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-26 · 2021 — الدورة الأولى\nquestion: ما مكافئ العدد (3AA)₁₆ في النظام العشري\n- [ ] option-1 | 23\n- [x] option-2 | 938\n- [ ] option-3 | 300\n- [ ] option-4 | 839\nexplanation:\nنقرأ أوزان خانات النظام السادس عشر من اليمين: **1، 16، 256**. ولأن A = 10، يصبح الحساب:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">3AA</mi><mn>16</mn></msub><mo>=</mo><mn>3</mn><mo>×</mo><mn>256</mn><mo>+</mo><mn>10</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>10</mn></mrow></math>\n```\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>768</mn><mo>+</mo><mn>160</mn><mo>+</mo><mn>10</mn><mo>=</mo><mn>938</mn></mrow></math>\n```\n\nإذن الاختيار الصحيح **938**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q12\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-27 · 2021 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-27 · 2021 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-27 · 2021 — الدورة الثانية\nquestion: للتحويل من النظام الثنائي إلى السادس عشر، نقسم العدد الثنائي إلى مجموعات ذات خانات…\n- [ ] option-1 | ثنائية\n- [x] option-2 | رباعية\n- [ ] option-3 | سداسية\n- [ ] option-4 | ثمانية\nexplanation:\nنجمّع البتات من اليمين في مجموعات من **أربع خانات**؛ لأن 2⁴ = 16، فتقابل كل مجموعة رقمًا واحدًا في النظام السادس عشر. نضيف أصفارًا يسار المجموعة الأولى عند الحاجة.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q13\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-28 · 2021 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-28 · 2021 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-28 · 2021 — الدورة الثانية\nquestion: ما شكل الشبكة المحلية الذي يقوم المحول (Switch) بربط أجهزتها؟\n- [x] option-1 | نجمية\n- [ ] option-2 | حلقية\n- [ ] option-3 | خطية\n- [ ] option-4 | مستطيلة\nexplanation:\nيقول الكتاب:\n\n> محول الشبكة Switch: جهاز يقوم بربط مجموعة أجهزة في شبكة محلية على شكل **مخطط نجمي Star** عبر نقطة مركزية ترتبط بها جميع أجهزة الحاسوب، حيث يقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية.\n\nالكتاب، ص 7\n\nاتصال الأجهزة كلها عبر **نقطة مركزية** يجعل شكل الشبكة نجميًا؛ وهذه النقطة هي المحوّل.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q14\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-29 · 2021 — الدورة الثانية\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-29 · 2021 — الدورة الثانية\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-29 · 2021 — الدورة الثانية\nquestion: ما مكافئ العدد السادس عشري (6C)₁₆ في النظام الثنائي؟\n- [ ] option-1 | 1101011\n- [ ] option-2 | 1111010\n- [ ] option-3 | 1101111\n- [x] option-4 | 1101100\nexplanation:\nنحوّل كل خانة سادسة عشرية إلى أربع بتات:\n\n- `6` تقابل `0110`.\n- `C` قيمتها 12، وتقابل `1100`.\n\nنصل المجموعتين:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">6C</mi><mn>16</mn></msub><mo>=</mo><msub><mn>01101100</mn><mn>2</mn></msub></mrow></math>\n```\n\nحذف الصفر في بداية العدد لا يغير قيمته، لذلك يطابق الناتج الاختيار **1101100**.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q15\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-30 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-30 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-30 · 2021 — الدورة الثالثة\nquestion: ما عدد البتات Bits التي يتكون منها MAC؟\n- [ ] option-1 | 32\n- [x] option-2 | 48\n- [ ] option-3 | 64\n- [ ] option-4 | 128\nexplanation:\nيقول الكتاب:\n\n> يتكون عنوان MAC من **48 بت**، و يتم تمثيله في أنظمة التشغيل على هيئة نظام العد السادس عشر Hexadecimal،\n\nالكتاب، ص 4\n\nنميّز طول العنوان عن طريقة عرضه: MAC طوله **48 بت** حتى لو كتبناه برموز النظام السادس عشر.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p043-q16\ntitle: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-31 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-31 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 43 · PDF 43 · السؤال 1-31 · 2021 — الدورة الثالثة\nquestion: ما أكبر رقم في النظام السادس عشر؟\n- [ ] option-1 | 9\n- [ ] option-2 | 10\n- [x] option-3 | F\n- [ ] option-4 | 16\nexplanation:\nرموز النظام السادس عشر هي 0–9 ثم A وB وC وD وE وF، وتمثل A–F القيم 10–15. لذلك أكبر رمز مسموح هو **F**؛ أما 16 فأساس النظام وليس رقمًا منفردًا فيه.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p044-q01\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-32 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-32 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-32 · 2021 — الدورة الثالثة\nquestion: ما الأمر المستخدم لفتح موجه سطر الأوامر في نظام تشغيل ويندوز؟\n- [ ] option-1 | IP\n- [ ] option-2 | Open\n- [x] option-3 | CMD\n- [ ] option-4 | Ping\nexplanation:\nنكتب **cmd** في نافذة تشغيل البرامج Run لفتح موجه سطر الأوامر. بعد فتحه يمكن كتابة أوامر الشبكة مثل ipconfig وping؛ أما تلك الأوامر فلا تفتح البرنامج نفسه. الكتاب، ص 18.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::mcq\nid: it-e-p044-q02\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-33 · 2021 — الدورة الثالثة\nkicker: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-33 · 2021 — الدورة الثالثة\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 1-33 · 2021 — الدورة الثالثة\nquestion: أي من الآتية لا يمثل عنوان MAC؟\n- [x] option-1 | DC-11-FH-43-11-23\n- [ ] option-2 | CC-DC-DD-43-37-11\n- [ ] option-3 | 8C-DC-D4-43-37-EF\n- [ ] option-4 | 8C-F1-F2-F3-Fe-EF\nexplanation:\nعنوان MAC يكتب برموز النظام السادس عشر: الأرقام 0–9 والحروف A–F فقط. العنوان **DC-11-FH-43-11-23** يحتوي الحرف H، وهو خارج الرموز المسموحة؛ لذلك لا يمثل عنوان MAC صحيحًا.\nhint: اقرأ السؤال والسياق المرفق قبل اختيار الإجابة.\nexample:\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n:::\n\n:::exam-question\nid: it-e-p044-q03\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-1 · 2019 — الدورة الأولى\nquestion: كيف يتم تعبئة جدول العناوين الـ MAC داخل المحول (Switch)؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-1 · 2019 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nكيف يتم تعبئة جدول العناوين الـ MAC داخل المحول (Switch)؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. يستخدم المحول العنوان الموجود في حقل عنوان MAC المصدر الموجود في بداية الرسالة (الإطار) للتعرف على مواقع الأجهزة في الشبكة.\n\n- ب. عندما يستقبل المحول أول رسالة من جهاز الحاسوب يتعرف مباشرة على عنوان MAC الخاص به ويضيفه داخل جدول العناوين مقترنًا مع المنفذ الذي أتت منه الرسالة.\nsolution:\nيتعلّم المحوّل عنوان الجهاز ومنفذه على خطوتين:\n\n1. يقرأ **MAC المصدر** من الإطار الوارد.\n2. يربط عنوان المصدر **بمنفذ استقبال الإطار** داخل جدول العناوين.\n\nوعند تحويل إطار لاحق، يبحث عن **MAC الهدف** ليختار منفذ الإرسال.\n\nأما FCS فيفحص سلامة الإطار؛ فلا يحدد موقع الجهاز. الكتاب، ص 9–10.\n:::\n\n:::exam-question\nid: it-e-p044-q04\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-2 · 2019 — الدورة الأولى\nquestion: حول العدد (10010)₂ إلى النظام السادس عشر.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-2 · 2019 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nحول العدد (10010)₂ إلى النظام السادس عشر.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n12\nsolution:\nنجمع البتات من اليمين في مجموعات رباعية، ونضيف أصفارًا يسار المجموعة الأولى عند الحاجة:\n\n`10010 → 0001 | 0010`\n\n- `0001` تمثل `1`.\n- `0010` تمثل `2`.\n\nإذن:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>10010</mn><mn>2</mn></msub><mo>=</mo><msub><mn>12</mn><mn>16</mn></msub></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p044-q05\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-3 · 2019 — الدورة الثانية\nquestion: ما هو عنوان الـ MAC وكيف تحصل عليه أجهزة الشبكة؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-3 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما هو عنوان الـ MAC وكيف تحصل عليه أجهزة الشبكة؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهو أحد أنظمة العنونة الفيزيائية يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها ويكون هذا العنوان فريدًا على مستوى جميع بطاقات الشبكة في العالم.\nsolution:\nيقول الكتاب:\n\n> عنوان الـ **MAC** هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nيتضمن السؤال مطلبين: **التعريف** وهو عنوان البطاقة الفيزيائي، و**مصدره** وهو المصنّع عند إنتاج البطاقة في نموذج الكتاب.\n:::\n\n:::exam-question\nid: it-e-p044-q06\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-4 · 2019 — الدورة الثانية\nquestion: كيف يعمل محول الشبكة LAN Switch في إرسال رسالة بين طرفين؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-4 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nكيف يعمل محول الشبكة LAN Switch في إرسال رسالة بين طرفين؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. يقوم جهاز المصدر ببناء الإطار وإرساله للمحول.\n\n- ب. تقوم محولات الشبكة بتحويل الرسالة للهدف عبر المنفذ المناسب بناء على الحقل الذي يحتوي على عنوان MAC الهدف الموجود في بداية الرسالة (الإطار).\n\n- ج. يوجد داخل كل محول جدول يربط عناوين MAC بأرقام المنافذ المتصلة بها.\nsolution:\n1. يبني جهاز المصدر إطارًا يحمل عنواني MAC للمصدر والهدف، ويرسله إلى المحوّل.\n2. يقرأ المحوّل **MAC الهدف** ويطابقه مع جدول العناوين الذي يربط كل عنوان بمنفذه.\n3. يمرر الإطار عبر المنفذ الموصل إلى الهدف.\n\nلا يختار المنفذ اعتمادًا على ترتيب الأجهزة في الرسم، بل على عنوان الهدف والجدول. الكتاب، ص 8–9.\n:::\n\n:::exam-question\nid: it-e-p044-q07\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-5 · 2019 — الدورة الثانية\nquestion: حول العدد (25)₁₀ إلى النظام الثنائي؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-5 · 2019 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nحول العدد (25)₁₀ إلى النظام الثنائي؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n(11001)₂. انظر طريقة الحل بالأسفل:\n\n\n- 25 ÷ 2 = 12 والباقي 1.\n\n- 12 ÷ 2 = 6 والباقي 0.\n\n- 6 ÷ 2 = 3 والباقي 0.\n\n- 3 ÷ 2 = 1 والباقي 1.\n\n- 1 ÷ 2 = 0 والباقي 1.\nsolution:\nنقسم على 2 ونحتفظ بالبواقي:\n\n- 25 ÷ 2 = 12 والباقي 1.\n- 12 ÷ 2 = 6 والباقي 0.\n- 6 ÷ 2 = 3 والباقي 0.\n- 3 ÷ 2 = 1 والباقي 1.\n- 1 ÷ 2 = 0 والباقي 1.\n\nنقرأ البواقي من الأسفل إلى الأعلى: **11001**. نتحقق: 16 + 8 + 1 = 25.\n:::\n\n:::exam-question\nid: it-e-p044-q08\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-6 · 2019 — الدورة الثالثة\nquestion: ارسم بنية الرسالة في طبقة ربط البيانات؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-6 · 2019 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nارسم بنية الرسالة في طبقة ربط البيانات؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n![بنية الرسالة في طبقة ربط البيانات](assets/lessons/adabi/information-technology/assets/it-e-p044-q08-fig01.webp)\nsolution:\nيتكون الإطار في الشكل الأصلي من الحقول الآتية:\n\n- **MAC الهدف وMAC المصدر:** يحددان طرفي الإرسال على الوصلة.\n- **جسم الرسالة:** يحمل المحتوى.\n- **FCS:** يستخدم لفحص سلامة الإطار.\n\nارسم الحقول كما في الصورة الأصلية على وجه الإجابة، مع الحفاظ على ترتيبها. الكتاب، ص 8–10.\n:::\n\n:::exam-question\nid: it-e-p044-q09\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-7 · 2020 — الدورة الثانية\nquestion: ما المقصود بكل من الآتية: بطاقة واجهة الشبكة، محول الشبكة (switch).\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-7 · 2020 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكل من الآتية: بطاقة واجهة الشبكة، محول الشبكة (switch).\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. هي أداة تربط بين الحاسوب والوسيط ولا تقوم بإرسال البيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\n- ب. جهاز يقوم بربط أجهزة في شبكة محلية بشكل نجمي Star عبر نقطة مركزية ويقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية.\nsolution:\n**بطاقة واجهة الشبكة NIC:** تصل جهاز الحاسوب بوسيط الاتصال، وتتحقق من خلوه من الإشارات قبل الإرسال وفق نموذج الدرس.\n\n**المحوّل Switch:** يجمع أجهزة الشبكة المحلية حول نقطة مركزية في مخطط نجمي وينظم مرور الإطارات بينها. البطاقة تخص اتصال جهاز واحد بالوسيط، أما المحوّل فيربط عدة أجهزة. الكتاب، ص 3 و7.\n:::\n\n:::exam-question\nid: it-e-p044-q10\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-8 · 2020 — الدورة الثانية\nquestion: وضح بالخطوات كيف يعمل محول الشبكة عندما يقوم المستخدم بإرسال رسالة لمستخدم آخر.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-8 · 2020 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nوضح بالخطوات كيف يعمل محول الشبكة عندما يقوم المستخدم بإرسال رسالة لمستخدم آخر.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. يقوم جهاز المصدر ببناء الإطار وإرساله للمحول.\n\n- ب. تقوم محولات الشبكة بتحويل الرسالة للهدف عبر المنفذ المناسب بناء على الحقل الذي يحتوي على عنوان MAC الهدف الموجود في بداية الرسالة (الإطار).\n\n- ج. يوجد داخل كل محول جدول يربط عناوين MAC بأرقام المنافذ المتصلة بها.\nsolution:\n1. يبني جهاز المصدر إطارًا يحمل عنواني MAC للمصدر والهدف، ويرسله إلى المحوّل.\n2. يقرأ المحوّل **MAC الهدف** ويطابقه مع جدول العناوين الذي يربط كل عنوان بمنفذه.\n3. يمرر الإطار عبر المنفذ الموصل إلى الهدف.\n\nلا يختار المنفذ اعتمادًا على ترتيب الأجهزة في الرسم، بل على عنوان الهدف والجدول. الكتاب، ص 8–9.\n:::\n\n:::exam-question\nid: it-e-p044-q11\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-9 · 2020 — الدورة الثانية\nquestion: كيف يتم تحديد عنوان MAC على جهازك في نظام تشغيل الأندرويد؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-9 · 2020 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nكيف يتم تحديد عنوان MAC على جهازك في نظام تشغيل الأندرويد؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. الضغط على أيقونة الإعدادات (settings) الموجودة داخل قائمة التطبيقات.\n\n- ب. تظهر قائمة نختار منها حول الجهاز about device.\n\n- ج. ثم نختار من قائمة حول الجهاز البند الحالة status.\n\n- د. في قائمة الحالة status تجد بندًا يوضح به الـ MAC للجهاز.\nsolution:\nنتبع ترتيب القوائم المصوّر في الدرس:\n\n1. نفتح **Settings**: الإعدادات.\n2. نختار **About device**: حول الجهاز.\n3. نفتح **Status**: الحالة.\n4. نقرأ **Wi-Fi MAC address**: عنوان واجهة Wi-Fi.\n\nهذه خطوات واجهة أندرويد التي يعرضها الكتاب. الكتاب، ص 5–6.\n:::\n\n:::exam-question\nid: it-e-p044-q12\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-10 · 2020 — الدورة الثالثة\nquestion: ما المقصود بكلٍّ مما يلي: بطاقة واجهة الشبكة.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-10 · 2020 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكلٍّ مما يلي: بطاقة واجهة الشبكة.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهي أداة تربط بين الحاسوب والوسيط ولا تقوم بإرسال البيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\nsolution:\nيقول الكتاب:\n\n> وهي **الأداة التي تربط جهاز الحاسوب بالوسيط** حيث لا تقوم هذه البطاقة بإرسال أي بيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\nالكتاب، ص 3\n\nتربط البطاقة **جهازًا واحدًا بوسيط الاتصال**؛ فلا نخلط بينها وبين المحوّل الذي يربط عدة أجهزة داخل الشبكة.\n:::\n\n:::exam-question\nid: it-e-p044-q13\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-11 · 2021 — الدورة الأولى\nquestion: أوجد قيمة كلا مما يأتي:\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-11 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nأوجد قيمة كلا مما يأتي:\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n- أ. العدد (B5)₁₆ في النظام الثنائي.\n- ب. العدد (1011010)₂ في النظام السادس العشري؟\nfinal-answer:\n- أ. (10110101)₂.\n\n- ب. (5A)₁₆.\nsolution:\n**أ. من السادس عشر إلى الثنائي**\n\n- `B` قيمتها 11، وتقابل `1011`.\n- `5` تقابل `0101`.\n\nنصل المجموعتين:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">B5</mi><mn>16</mn></msub><mo>=</mo><msub><mn>10110101</mn><mn>2</mn></msub></mrow></math>\n```\n\n**ب. من الثنائي إلى السادس عشر**\n\nنجمع من اليمين: `1011010 → 0101 | 1010`.\n\nالمجموعتان تقابلان `5` و`A`، لذلك:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>1011010</mn><mn>2</mn></msub><mo>=</mo><msub><mi mathvariant=\"normal\">5A</mi><mn>16</mn></msub></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p044-q14\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-12 · 2021 — الدورة الأولى\nquestion: ما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-12 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما الفرق بين العنوان المنطقي والعنوان الفيزيائي؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- العنوان المنطقي: أحد أقسام العنونة في شبكات الحاسوب وهو عنوان فريد لكل جهاز على شبكة الاتصال يستخدم من قبل أجهزة الشبكات للوصول إلى الجهاز ويرمز له (IP).\n\n- العنوان الفيزيائي: هو أحد أنظمة العنونة الفيزيائية يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها ويكون هذا العنوان فريدًا على مستوى جميع بطاقات الشبكة في العالم.\nsolution:\nنقارن بحسب **موضع استعمال العنوان**:\n\n- **MAC:** عنوان واجهة الشبكة على الوصلة المحلية.\n- **IP:** عنوان منطقي يضم جزءًا للشبكة وجزءًا للجهاز، ويستخدم للتوجيه بين الشبكات.\n\nلذلك تحتفظ البطاقة بعنوانها الفيزيائي في نموذج الدرس عند نقلها إلى شبكة أخرى، بينما قد يتغير عنوانها المنطقي. الكتاب، ص 3–4 و11–12.\n:::\n\n:::exam-question\nid: it-e-p044-q15\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-13 · 2021 — الدورة الأولى\nquestion: كيف يعمل المحول Switch بتعبئة عناوين MAC؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-13 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nكيف يعمل المحول Switch بتعبئة عناوين MAC؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- أ. يستخدم المحول عنوان MAC المصدر للتعرف على مواقع الأجهزة.\n\n- ب. عندما يستقبل المحول أول رسالة من جهاز الحاسوب يتعرف مباشرة على عنوان الـ MAC ويضيفه داخل جدول العناوين مقترنًا مع رقم المنفذ الذي أتت منه الرسالة.\n\n- ج. يستخدم المحول حقل FCS لتفحص الأخطاء للتأكد من صلاحية الإطار.\nsolution:\nيتعلّم المحوّل عنوان الجهاز ومنفذه على خطوتين:\n\n1. يقرأ **MAC المصدر** من الإطار الوارد.\n2. يربط عنوان المصدر **بمنفذ استقبال الإطار** داخل جدول العناوين.\n\nوعند تحويل إطار لاحق، يبحث عن **MAC الهدف** ليختار منفذ الإرسال.\n\nأما FCS فيفحص سلامة الإطار؛ فلا يحدد موقع الجهاز. الكتاب، ص 9–10.\n:::\n\n:::exam-question\nid: it-e-p044-q16\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-14 · 2021 — الدورة الأولى\nquestion: ما المقصود بكل من الآتية: بطاقة واجهة الشبكة NIC.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-14 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكل من الآتية: بطاقة واجهة الشبكة NIC.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهي أداة تربط بين الحاسوب والوسيط ولا تقوم بإرسال البيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\nsolution:\nيقول الكتاب:\n\n> وهي **الأداة التي تربط جهاز الحاسوب بالوسيط** حيث لا تقوم هذه البطاقة بإرسال أي بيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\nالكتاب، ص 3\n\nالجزء الأول من التعريف يبين وظيفة الربط، والجزء الثاني يبين شرط الإرسال في نموذج الدرس: **خلو الوسيط من الإشارات**.\n:::\n\n:::exam-question\nid: it-e-p044-q17\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-15 · 2021 — الدورة الأولى\nquestion: ما عنوان MAC؟ وكيف تحصل عليه أجهزة الشبكة؟\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-15 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما عنوان MAC؟ وكيف تحصل عليه أجهزة الشبكة؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهو أحد أنظمة العنونة الفيزيائية يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها ويكون هذا العنوان فريدًا على مستوى جميع بطاقات الشبكة في العالم.\nsolution:\nيقول الكتاب:\n\n> عنوان الـ **MAC** هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nالتعريف يصف MAC بأنه عنوان فيزيائي للبطاقة، ثم يوضح الاقتباس كيفية حصولها عليه: **ينشئه المصنّع عند إنتاجها**.\n:::\n\n:::exam-question\nid: it-e-p044-q18\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-16 · 2021 — الدورة الأولى\nquestion: لديك البيانات الآتية (B846FA1043D7)، مثل هذه البيانات بالصيغ الثلاث لعنوان فيزيائي (MAC).\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-16 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nلديك البيانات الآتية (B846FA1043D7)، مثل هذه البيانات بالصيغ الثلاث لعنوان فيزيائي (MAC).\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- B846FA.1043D7\n\n- B8:46:FA:10:43:D7\n\n- B8-46-FA-10-43-D7\nsolution:\nنحافظ على الرموز الاثني عشر **B846FA1043D7** وترتيبها؛ التغيير في الفواصل فقط:\n\n- مجموعتان من ستة رموز: **B846FA.1043D7**.\n- ست مجموعات من رمزين: **B8:46:FA:10:43:D7**.\n- المجموعات نفسها بشرطات: **B8-46-FA-10-43-D7**.\n\nكل رمزين يمثلان بايتًا، فلا نضيف رمزًا أو نحذفه عند إعادة التنسيق.\n:::\n\n:::exam-question\nid: it-e-p044-q19\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-17 · 2021 — الدورة الأولى\nquestion: حول العدد (150)₁₀ إلى ما يكافئه بالنظام السادس عشر.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-17 · 2021 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nحول العدد (150)₁₀ إلى ما يكافئه بالنظام السادس عشر.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- 150 ÷ 16 = 9 والباقي 6،\n- و9 ÷ 16 = 0 والباقي 9،\n\nفيكون ناتج التحويل (96)₁₆.\nsolution:\nنقسم على أساس النظام المطلوب، وهو **16**:\n\n1. نقسم 150 على 16، فيكون الناتج **9** والباقي **6**.\n2. نقسم 9 على 16، فيكون الناتج **0** والباقي **9**.\n\nنقرأ البواقي من الأخير إلى الأول، فيكون الناتج:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>150</mn><mn>10</mn></msub><mo>=</mo><msub><mn>96</mn><mn>16</mn></msub></mrow></math>\n```\n\nوللتحقق:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>9</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>150</mn></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p044-q20\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-18 · 2021 — الدورة الثانية\nquestion: وضح المقصود بكل من المصطلحات الآتية: بطاقة واجهة الشبكة.\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-18 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nوضح المقصود بكل من المصطلحات الآتية: بطاقة واجهة الشبكة.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهي أداة تربط بين الحاسوب والوسيط ولا تقوم بإرسال البيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\nsolution:\nيقول الكتاب:\n\n> وهي **الأداة التي تربط جهاز الحاسوب بالوسيط** حيث لا تقوم هذه البطاقة بإرسال أي بيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\nالكتاب، ص 3\n\nنربط اسم البطاقة بوظيفتها: هي **واجهة الجهاز مع وسيط الاتصال**، ويشرح النص متى تبدأ الإرسال في النموذج الوارد في الكتاب.\n:::\n\n:::exam-question\nid: it-e-p044-q21\ntitle: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-19 · 2021 — الدورة الثانية\nquestion: ما قيمة كلا مما يأتي:\nreference: مجموعة الامتحانات · ص 44 · PDF 44 · السؤال 2-19 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قيمة كلا مما يأتي:\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n- أ. العدد (A69)₁₆ في النظام العشري.\n- ب. العدد (1011110101011)₂ في النظام السادس عشري.\nfinal-answer:\n- أ. (2665)₁₀.\n\n- ب. (17AB)₁₆.\nsolution:\n**أ. من السادس عشر إلى العشري**\n\nقيمة A هي 10، ونستخدم أوزان الخانات:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">A69</mi><mn>16</mn></msub><mo>=</mo><mn>10</mn><mo>×</mo><msup><mn>16</mn><mn>2</mn></msup><mo>+</mo><mn>6</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>9</mn></mrow></math>\n```\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>2560</mn><mo>+</mo><mn>96</mn><mo>+</mo><mn>9</mn><mo>=</mo><mn>2665</mn></mrow></math>\n```\n\n**ب. من الثنائي إلى السادس عشر**\n\nنقسم من اليمين: `0001 | 0111 | 1010 | 1011`.\n\nتقابل المجموعات بالترتيب `1`، `7`، `A`، `B`؛ لذلك الناتج **17AB**.\n:::\n\n:::exam-question\nid: it-e-p045-q01\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-20 · 2021 — الدورة الثانية\nquestion: علل: نحتاج لكل من العنونة الفيزيائية والمنطقية في شبكة الحاسوب.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-20 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nعلل: نحتاج لكل من العنونة الفيزيائية والمنطقية في شبكة الحاسوب.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n- العنونة الفيزيائية: لأن العنونة الفيزيائية تساعد في نقل البيانات داخل الشبكة المحلية بين الأجهزة.\n\n- أما العنونة المنطقية فتعمل على نقل البيانات بين الأجهزة في شبكات مختلفة.\nsolution:\nالوصول عبر شبكات متعددة يتطلب عنوانًا يحدد **الجهاز النهائي وشبكته**؛ لذلك نستخدم IP للتوجيه. لكن كل خطوة محلية في الرحلة تحتاج عنوان واجهة الإرسال وواجهة المحطة التالية، فتستخدم MAC. تبقى وجهة IP ثابتة، ويتغير إطار MAC عند انتقال الرسالة من موجه إلى آخر؛ لذا يؤدي كل نظام وظيفة مكملة للآخر. الكتاب، ص 21–22.\n:::\n\n:::exam-question\nid: it-e-p045-q02\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-21 · 2021 — الدورة الثانية\nquestion: ما قيمة (189)₁₀ في النظام السادس عشر.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-21 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قيمة (189)₁₀ في النظام السادس عشر.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n(BD)₁₆.\nsolution:\nنقسم 189 على 16، فنحصل على **11** والباقي **13**.\n\nفي النظام السادس عشر 11 تمثل B، و13 تمثل D؛ نكتب رمز خارج القسمة ثم رمز الباقي:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>189</mn><mn>10</mn></msub><mo>=</mo><msub><mi mathvariant=\"normal\">BD</mi><mn>16</mn></msub></mrow></math>\n```\n\nوللتحقق:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>11</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>13</mn><mo>=</mo><mn>189</mn></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p045-q03\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-22 · 2021 — الدورة الثانية\nquestion: ارسم تنسيق الرسالة (الإطار) في طبقة ربط البيانات، وعلل احتواء الرسالة على حقل FCS.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-22 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nارسم تنسيق الرسالة (الإطار) في طبقة ربط البيانات، وعلل احتواء الرسالة على حقل FCS.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nللتأكد من صلاحية الإطار خوفًا من أي تغير للإطار في الطريق بسبب التشويش.\n\n![تنسيق الرسالة في طبقة ربط البيانات](assets/lessons/adabi/information-technology/assets/it-e-p045-q03-fig01.webp)\nsolution:\nيتضمن السؤال **الرسم والتعليل**:\n\n1. **الرسم:** نحافظ على حقول الصورة الأصلية: MAC الهدف، MAC المصدر، جسم الرسالة، FCS.\n2. **التعليل:** قد تتغير بعض البتات بسبب التشويش أثناء النقل؛ لذلك يفحص المحوّل قيمة FCS ليتحقق من سلامة الإطار.\n\nإذا فشل الفحص، يتخلص المحوّل من الإطار غير الصالح بدل تمريره. الكتاب، ص 8–10.\n:::\n\n:::exam-question\nid: it-e-p045-q04\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-23 · 2021 — الدورة الثانية\nquestion: علل لما يلي: عدم اختلاف عنوان الـ MAC لجهاز الحاسوب رغم انتقاله من شبكة لأخرى؟\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-23 · 2021 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nعلل لما يلي: عدم اختلاف عنوان الـ MAC لجهاز الحاسوب رغم انتقاله من شبكة لأخرى؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nلأنه عنوان يتم إنشاؤه من قبل المصنع وهو فريد على مستوى جميع بطاقات الشبكات في العالم.\nsolution:\nعنوان MAC مرتبط **ببطاقة واجهة الشبكة نفسها** ويعيّنه المصنّع في النموذج الذي يقدمه الكتاب. نقل البطاقة إلى شبكة أخرى لا يبدّل هويتها الفيزيائية، ولذلك لا يتغير عنوانها لمجرد الانتقال؛ العنوان الذي قد يتغير بتغير الشبكة هو IP. الكتاب، ص 4.\n:::\n\n:::exam-question\nid: it-e-p045-q05\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-24 · 2021 — الدورة الثالثة\nquestion: ما عنوان الـ MAC وكيف تحصل عليه أجهزة الشبكة؟\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-24 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما عنوان الـ MAC وكيف تحصل عليه أجهزة الشبكة؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهو أحد أنظمة العنونة الفيزيائية يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها ويكون هذا العنوان فريدًا على مستوى جميع بطاقات الشبكة في العالم.\nsolution:\nيقول الكتاب:\n\n> عنوان الـ **MAC** هو أحد أنظمة العنونة الفيزيائية حيث يتم إنشاؤه من قبل المصنع بشكل فيزيائي على بطاقة الشبكة عند إنتاجها،\n\nالكتاب، ص 4\n\nلإكمال الجواب نذكر الأمرين معًا: MAC **عنوان فيزيائي لبطاقة الشبكة**، وتمنحه الشركة المصنّعة للبطاقة في نموذج الدرس.\n:::\n\n:::exam-question\nid: it-e-p045-q06\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-25 · 2021 — الدورة الثالثة\nquestion: ما قيمة (171)₁₀ في النظام السادس عشري؟\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-25 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قيمة (171)₁₀ في النظام السادس عشري؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n(AB)₁₆.\nsolution:\nنقسم 171 على 16، فنحصل على **10** والباقي **11**.\n\nفي النظام السادس عشر 10 تمثل A، و11 تمثل B؛ نكتب رمز خارج القسمة ثم رمز الباقي:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>171</mn><mn>10</mn></msub><mo>=</mo><msub><mi mathvariant=\"normal\">AB</mi><mn>16</mn></msub></mrow></math>\n```\n\nوللتحقق:\n\n```mathml\n<math dir=\"ltr\"><mrow><mn>10</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>11</mn><mo>=</mo><mn>171</mn></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p045-q07\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-26 · 2021 — الدورة الثالثة\nquestion: ما وظيفة كلٍّ من: العنونة الفيزيائية.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-26 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة كلٍّ من: العنونة الفيزيائية.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nتساعد البيانات في التنقل داخل الشبكة المحلية.\nsolution:\nيقول الكتاب:\n\n> تعرفنا في الطبقة الثانية على **العنونة الفيزيائية** التي تساعد البيانات في التنقل داخل الشبكة المحلية،\n\nالكتاب، ص 11\n\nنطاق عمل العنونة الفيزيائية هنا هو **داخل الشبكة المحلية**؛ أما الوصول عبر شبكات مختلفة فيحتاج العنونة المنطقية.\n:::\n\n:::exam-question\nid: it-e-p045-q08\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-27 · 2021 — الدورة الثالثة\nquestion: ما المقصود بكل من: بطاقة واجهة الشبكة NIC.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-27 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكل من: بطاقة واجهة الشبكة NIC.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهي أداة تربط بين الحاسوب والوسيط ولا تقوم بإرسال البيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\nsolution:\nيقول الكتاب:\n\n> وهي **الأداة التي تربط جهاز الحاسوب بالوسيط** حيث لا تقوم هذه البطاقة بإرسال أي بيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\nالكتاب، ص 3\n\nالوظيفة الأساسية هي **وصل الحاسوب بالوسيط**، مع التحقق من خلو الوسيط من الإشارات قبل الإرسال وفق الدرس.\n:::\n\n:::exam-question\nid: it-e-p045-q09\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-28 · 2021 — الدورة الثالثة\nquestion: أوجد قيمة كلٍّ مما يأتي:\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-28 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nأوجد قيمة كلٍّ مما يأتي:\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n- أ. العدد (A5)₁₆ في النظام العشري.\n- ب. العدد (10001)₂ في النظام السادس العشري.\nfinal-answer:\n- أ. (165)₁₀.\n\n- ب. (11)₁₆.\nsolution:\n**أ. من السادس عشر إلى العشري**\n\nقيمة A هي 10، ووزن الخانة اليسرى 16:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">A5</mi><mn>16</mn></msub><mo>=</mo><mn>10</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>5</mn><mo>=</mo><msub><mn>165</mn><mn>10</mn></msub></mrow></math>\n```\n\n**ب. من الثنائي إلى السادس عشر**\n\nنكمل المجموعة اليسرى بالأصفار: `10001 → 0001 | 0001`.\n\nتقابل المجموعتان `1` و`1`:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>10001</mn><mn>2</mn></msub><mo>=</mo><msub><mn>11</mn><mn>16</mn></msub></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p045-q10\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-29 · 2021 — الدورة الثالثة\nquestion: ما المقصود بكلٍّ من: حقل FCS.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-29 · 2021 — الدورة الثالثة\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكلٍّ من: حقل FCS.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nهو حقل موجود لتفحص الأخطاء للتأكد من صلاحية الإطار.\nsolution:\nيقول الكتاب:\n\n> يستخدم المحول قيمة FCS (Frame Check Sequence) الموجودة في **حقل تفحص الأخطاء** الموجودة في نهاية الرسالة (الإطار).\n\nالكتاب، ص 10\n\nFCS يخص **سلامة الإطار**؛ يقارن المحوّل قيمة الفحص المحسوبة بالقيمة المرفقة ليكشف تغير البيانات أثناء النقل.\n:::\n\n:::exam-question\nid: it-e-p045-q11\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-30 · 2022 — الدورة الأولى\nquestion: ما المقصود بكل من الآتية: محول الشبكة (Switch).\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-30 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما المقصود بكل من الآتية: محول الشبكة (Switch).\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nجهاز يقوم بربط عدة أجهزة على شكل مخطط نجمي بنقطة مركزية مكونًا شبكة محلية، ويعمل على تنظيم نقل البيانات بين أجهزة الشبكة.\nsolution:\nيقول الكتاب:\n\n> **محول الشبكة Switch**: جهاز يقوم بربط مجموعة أجهزة في شبكة محلية على شكل مخطط نجمي Star عبر نقطة مركزية ترتبط بها جميع أجهزة الحاسوب، حيث يقوم بتنظيم مرور البيانات بين الأجهزة على الشبكة المحلية.\n\nالكتاب، ص 7\n\nيتضمن التعريف وظيفتين مترابطتين: **ربط الأجهزة** حول نقطة مركزية، ثم **تنظيم مرور البيانات** بينها.\n:::\n\n:::exam-question\nid: it-e-p045-q12\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-31 · 2022 — الدورة الأولى\nquestion: علل: عنوان الـ MAC هو أحد أنظمة العنونة الفيزيائية.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-31 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nعلل: عنوان الـ MAC هو أحد أنظمة العنونة الفيزيائية.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nلأنه من الشركة المصنعة لبطاقة واجهة الشبكة لا يتغير وفريد.\nsolution:\nعنوان MAC مرتبط **ببطاقة واجهة الشبكة نفسها** ويعيّنه المصنّع في النموذج الذي يقدمه الكتاب. نقل البطاقة إلى شبكة أخرى لا يبدّل هويتها الفيزيائية، ولذلك لا يتغير عنوانها لمجرد الانتقال؛ العنوان الذي قد يتغير بتغير الشبكة هو IP. الكتاب، ص 4.\n:::\n\n:::exam-question\nid: it-e-p045-q13\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-32 · 2022 — الدورة الأولى\nquestion: ما قيمة كل مما يأتي:\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-32 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قيمة كل مما يأتي:\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n- أ. (1A7)₁₆ في النظام العشري.\n- ب. (011100001100)₂ في النظام السادس عشر.\n- ج. (100111)₂ في النظام العشري.\nfinal-answer:\n- أ. 423.\n\n- ب. 70C.\n\n- ج. 39.\nsolution:\n**أ. من السادس عشر إلى العشري**\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">1A7</mi><mn>16</mn></msub><mo>=</mo><mn>1</mn><mo>×</mo><mn>256</mn><mo>+</mo><mn>10</mn><mo>×</mo><mn>16</mn><mo>+</mo><mn>7</mn><mo>=</mo><mn>423</mn></mrow></math>\n```\n\n**ب. من الثنائي إلى السادس عشر**\n\nنقسم إلى مجموعات رباعية: `0111 | 0000 | 1100`.\n\nتقابلها `7` و`0` و`C`، لذلك الناتج **70C**.\n\n**ج. من الثنائي إلى العشري**\n\nنأخذ أوزان الخانات التي قيمتها 1:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>100111</mn><mn>2</mn></msub><mo>=</mo><mn>32</mn><mo>+</mo><mn>4</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>39</mn></mrow></math>\n```\n:::\n\n:::exam-question\nid: it-e-p045-q14\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-33 · 2022 — الدورة الأولى\nquestion: تأمل بنية الرسالة (الإطار) الآتية، ثم أجب:\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-33 · 2022 — الدورة الأولى\nanswer-label: إجابة المفتاح المرفق\nbody:\nتأمل بنية الرسالة (الإطار) الآتية، ثم أجب:\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n![بنية الإطار وفيها الحقلان المرقمان](assets/lessons/adabi/information-technology/assets/it-e-p045-q14-fig01.webp)\n\n- أ. إلى ماذا يشير الرقم (1)؟\n- ب. ما وظيفة الحقل المشار إليه بالرقم (2)؟\n- ج. ما وظيفة الأمر (cmd) داخل نافذة التشغيل (Run)؟\nfinal-answer:\n- أ. جسم الإطار.\n\n- ب. تفحص الأخطاء: التأكد من صلاحية الإطار وإتلافه في حالة التشويش.\n\n- ج. تشغيل موجه الأوامر.\nsolution:\nنجيب عن كل فرع على حدة:\n\n- **أ. الحقل (1):** جسم الإطار الذي يحمل محتوى الرسالة.\n- **ب. الحقل (2):** تفحص الأخطاء **FCS**؛ يتحقق المحوّل به من سلامة الإطار، ويتخلص من الإطار إذا فشل الفحص.\n- **ج. الأمر `cmd`:** يفتح موجه سطر الأوامر عند كتابته في Run؛ فهو أمر لتشغيل البرنامج، وليس حقلًا من الإطار.\n\nالكتاب، ص 8–10 و18.\n:::\n\n:::exam-question\nid: it-e-p045-q15\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-34 · 2022 — الدورة الثانية\nquestion: كيف يتخذ المحول القرار المناسب لتحويل الرسالة للمنفذ الصحيح؟\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-34 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nكيف يتخذ المحول القرار المناسب لتحويل الرسالة للمنفذ الصحيح؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nعن طريق عنوان MAC الهدف الموجود في الإطار ومقارنته مع جدول العناوين وتحويل الرسالة إلى المنفذ المطلوب.\nsolution:\nيقول الكتاب:\n\n> تقوم محولات الشبكة بتحويل الرسالة للجهاز الهدف عبر المنفذ المناسب بناءً على الحقل الذي يحتوي على **عنوان الـ MAC الهدف** الموجود في بداية الرسالة (الإطار) كما في الشكل أدناه.\n\nالكتاب، ص 8\n\nنقرأ **MAC الهدف** أولًا، ثم نبحث عنه في جدول العناوين. الربط بين العنوان والمنفذ هو الذي يحدد مسار الإطار داخل المحوّل.\n:::\n\n:::exam-question\nid: it-e-p045-q16\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-35 · 2022 — الدورة الثانية\nquestion: وضح بالرسمة آلية توصيل محول الشبكة Switch داخل شبكة محلية.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-35 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nوضح بالرسمة آلية توصيل محول الشبكة Switch داخل شبكة محلية.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\n![محول شبكة في مركز مخطط نجمي](assets/lessons/adabi/information-technology/assets/it-e-p045-q16-fig01.webp)\nsolution:\nالمحوّل هو **نقطة المركز** في الرسم، وتتصل به الأجهزة بخطوط مستقلة؛ لذلك يظهر التوصيل **نجميًا**. المطلوب تمثيل علاقة كل جهاز بالمحوّل، لا توصيل الأجهزة في حلقة أو توصيل كل جهاز بجاره. احتفظ بصورة التوصيل الأصلية في الإجابة. الكتاب، ص 7.\n:::\n\n:::exam-question\nid: it-e-p045-q17\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-36 · 2022 — الدورة الثانية\nquestion: ما وظيفة كل من: بطاقة واجهة الشبكة.\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-36 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما وظيفة كل من: بطاقة واجهة الشبكة.\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\nfinal-answer:\nأداة لربط الحاسوب مع الوسيط وعدم نقل البيانات إلا بعد التأكد من خلو الوسيط من الإشارات خوفًا من تداخل البيانات.\nsolution:\nيقول الكتاب:\n\n> وهي **الأداة التي تربط جهاز الحاسوب بالوسيط** حيث لا تقوم هذه البطاقة بإرسال أي بيانات إلا بعد التأكد من خلو الوسيط من الإشارات.\n\nالكتاب، ص 3\n\nالتحقق من خلو الوسيط قبل الإرسال يوضح دور البطاقة في **تجنب تداخل البيانات** في نموذج الدرس.\n:::\n\n:::exam-question\nid: it-e-p045-q18\ntitle: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-37 · 2022 — الدورة الثانية\nquestion: ما قيمة كل مما يأتي؟\nreference: مجموعة الامتحانات · ص 45 · PDF 45 · السؤال 2-37 · 2022 — الدورة الثانية\nanswer-label: إجابة المفتاح المرفق\nbody:\nما قيمة كل مما يأتي؟\n\n### الدرس الأول — الطبقة الثانية: طبقة ربط البيانات\n\n- أ. العدد (A3)₁₆ في النظام الثنائي.\n- ب. العدد (192)₁₀ في النظام السادس عشري.\nfinal-answer:\n- أ. 10100011.\n\n- ب. C0.\nsolution:\n**أ. من السادس عشر إلى الثنائي**\n\n- `A` تقابل `1010`.\n- `3` تقابل `0011`.\n\nنصل المجموعتين:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mi mathvariant=\"normal\">A3</mi><mn>16</mn></msub><mo>=</mo><msub><mn>10100011</mn><mn>2</mn></msub></mrow></math>\n```\n\n**ب. من العشري إلى السادس عشر**\n\nنقسم 192 على 16، فنحصل على 12 والباقي 0. والعدد 12 يمثله الرمز C، لذلك:\n\n```mathml\n<math dir=\"ltr\"><mrow><msub><mn>192</mn><mn>10</mn></msub><mo>=</mo><msub><mi mathvariant=\"normal\">C0</mi><mn>16</mn></msub></mrow></math>\n```\n:::";

